fn hex_mesh() -> fem_mesh::Mesh<3> {
    read_mfem(HEX_MESH.as_bytes())
        .expect("hex mesh parses")
        .mesh3d
        .expect("expected a 3-D mesh")
}

/// Evaluate every unit-dof field of an HDiv `RT_k` space at the transcript
/// point with the given open-basis variant and return the values in the
/// transcript's field order (`std::map` alphabetical), 3 components per
/// field — the same layout as the archived MFEM token tables.
fn unit_field_values<const N: usize>(open: HexRtOpen) -> Vec<f64> {
    let mesh = hex_mesh();
    let sp = HDivSpace::new(mesh.clone(), N as u8);
    let n = sp.n_dofs();
    assert_eq!(n, 3 * (N + 1) * (N + 1) * (N + 2));
    assert_eq!(sp.element_dofs(0), &(0..n as u32).collect::<Vec<_>>()[..]);
    assert!(sp.element_signs(0).iter().all(|&s| s == 1.0));

    // find_points reports `[0,1]^3` reference coordinates on hexes since D721
    // (`to_factory_coords` became the identity); the basis is evaluated there
    // and transformed with the contravariant Piola map, `phi = J psi / det J` —
    // exactly `GridFunction::evaluate_vector_at_element`'s H(div) arm.
    let pt = [0.65_f64, 0.84, 0.6];
    let (elem_ids, ips) = find_points(&mesh, &pt, 1);
    assert_eq!(elem_ids[0], 0, "point must be found in the single hex");
    let xi = [ips[0][0], ips[0][1], ips[0][2]];

    let el = match open {
        HexRtOpen::GaussLegendre => HexRTk::new_gauss_legendre(N),
        HexRtOpen::IntegratedGLL => HexRTk::new(N),
    };
    let mut psi = vec![0.0_f64; el.n_dofs() * 3];
    el.eval_basis_vec(&xi, &mut psi);

    // Contravariant Piola of the `[0,1]³` isoparametric hex frame (D757
    // re-anchor after D721: `HexRTk` and `find_points` both live on MFEM's
    // unit cube now, so `J = diag(h)` with the raw edge lengths
    // `h = (1.0, 1.2, 0.8)` — the former `[-1,1]` frame used `h/2` and a
    // `det = 0.12` three-quarters smaller, which is the exact ×4 the transcript
    // comparison flagged).  `phi = J psi / det J`.
    let det = 1.0 * 1.2 * 0.8;
    let jscale = [1.0 / det, 1.2 / det, 0.8 / det];

    // Transcript field order: alphabetical over "f0".."f{n-1}".
    let mut order: Vec<usize> = (0..n).collect();
    order.sort_by_key(|&k| format!("f{k}"));

    let mut out = Vec::with_capacity(n * 3);
    for &k in &order {
        for c in 0..3 {
            out.push(jscale[c] * psi[k * 3 + c]);
        }
    }
    out
}

fn check_against_mfem<const N: usize>(mfem_tokens: &str, tag: &str) {
    let want: Vec<f64> = mfem_tokens
        .split_whitespace()
        .map(|t| t.parse::<f64>().expect("token parses"))
        .collect();
    let got = unit_field_values::<N>(HexRtOpen::GaussLegendre);
    assert_eq!(got.len(), want.len(), "{tag}: token count");
    let mut worst = 0.0_f64;
    for (i, (&g, &w)) in got.iter().zip(want.iter()).enumerate() {
        let diff = (g - w).abs();
        // The transcripts carry 6 significant digits; "0" tokens are exact
        // structural zeros on both sides.
        assert!(
            diff <= 1e-5 * (1.0 + w.abs()) + 1e-12,
            "{tag} token {i}: fem-rs {g} vs mfem {w}"
        );
        worst = worst.max(diff);
    }
    println!("{tag}: max |diff| = {worst:.3e} over {} tokens", want.len());
}

/// RT1: all 36 unit-dof fields at the generic point match the MFEM 4.10
/// get-values transcript (the round-40 36-token IntegratedGLL residual).
#[test]
fn rt1_unit_fields_match_mfem_get_values() {
    check_against_mfem::<1>(MFEM_RT1, "RT1 nodal-GL");
}

/// RT2: all 108 unit-dof fields at the generic point match the MFEM 4.10
/// get-values transcript (the round-40 108-token IntegratedGLL residual).
#[test]
fn rt2_unit_fields_match_mfem_get_values() {
    check_against_mfem::<2>(MFEM_RT2, "RT2 nodal-GL");
}
